        if (
            connection.execute(
                "SELECT 1 FROM schema_metadata WHERE key = ?",
                (SLA_AUTH_MARKER,),
            ).fetchone()
            is not None
        ):
            # 其他连接已完成迁移，直接释放写锁。
            connection.execute("COMMIT")
